list_shipping_profiles.code:
final response = await client.shippingProfiles.listShippingProfiles(
  queryParams: {'search': 'metro', 'sort': 'name', 'order': 'asc', 'limit': 20},
);
final result = response.map as Map;
for (final shippingProfile in result['shipping_profiles'] as List) {
  print('${(shippingProfile as Map)['id']} ${shippingProfile['name']} ${shippingProfile['rule_preference']}');
}
final pagination = result['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');

count_shipping_profiles.code:
final response = await client.shippingProfiles
    .countShippingProfiles(queryParams: {'default': 'true'});
print((response.map as Map)['total']);

create_shipping_profile.code:
