get_shipping_profile.code:
final response = await client.shippingProfiles.getShippingProfile(12);
final shippingProfile = (response.map as Map)['shipping_profile'] as Map;
print('${shippingProfile['name']} ${shippingProfile['rule_preference']} ${shippingProfile['default']}');
